import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableModule } from '@angular/material/table';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';
import { MatDialogModule, MatDialog } from '@angular/material/dialog';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatTooltipModule } from '@angular/material/tooltip';
import { InternService } from '../../core/services/intern.service';
import { AuthService } from '../../core/services/auth.service';
import { Intern } from '../../core/models/models';

@Component({
    selector: 'app-intern-list',
    standalone: true,
    imports: [CommonModule, FormsModule, MatTableModule, MatButtonModule, MatIconModule,
        MatFormFieldModule, MatInputModule, MatSelectModule, MatSnackBarModule,
        MatDialogModule, MatProgressSpinnerModule, MatTooltipModule],
    template: `
    <div class="page-container">
      <div class="page-header">
        <div class="header-row">
          <div>
            <h1>Intern Management</h1>
            <p>Manage your intern data, upload Excel files, and track performance</p>
          </div>
          <div class="header-actions">
            <label class="upload-btn" matTooltip="Upload .xlsx file">
              <mat-icon>cloud_upload</mat-icon>
              <span>Upload Excel</span>
              <input type="file" accept=".xlsx,.xls" (change)="onFileUpload($event)" hidden>
            </label>
          </div>
        </div>
      </div>

      <!-- Search & Filters -->
      <div class="search-bar">
        <mat-form-field appearance="outline" style="flex: 1; min-width: 250px;">
          <mat-label>Search interns...</mat-label>
          <input matInput [(ngModel)]="searchQuery" (input)="onSearch()" placeholder="Name, ID, or email">
          <mat-icon matPrefix>search</mat-icon>
        </mat-form-field>

        <mat-form-field appearance="outline" style="width: 160px;">
          <mat-label>Status</mat-label>
          <mat-select [(ngModel)]="statusFilter" (selectionChange)="onSearch()">
            <mat-option value="">All</mat-option>
            <mat-option value="ACTIVE">Active</mat-option>
            <mat-option value="COMPLETED">Completed</mat-option>
            <mat-option value="DROPPED">Dropped</mat-option>
          </mat-select>
        </mat-form-field>

        <mat-form-field appearance="outline" style="width: 160px;">
          <mat-label>Batch</mat-label>
          <mat-select [(ngModel)]="batchFilter" (selectionChange)="onSearch()">
            <mat-option value="">All</mat-option>
            <mat-option *ngFor="let b of batches" [value]="b">{{ b }}</mat-option>
          </mat-select>
        </mat-form-field>

        <mat-form-field appearance="outline" style="width: 160px;">
          <mat-label>Department</mat-label>
          <mat-select [(ngModel)]="deptFilter" (selectionChange)="onSearch()">
            <mat-option value="">All</mat-option>
            <mat-option *ngFor="let d of departments" [value]="d">{{ d }}</mat-option>
          </mat-select>
        </mat-form-field>
      </div>

      <!-- Upload Result -->
      <div *ngIf="uploadResult" class="upload-result"
           [class.success]="uploadResult.errorRows === 0"
           [class.warning]="uploadResult.errorRows > 0">
        <mat-icon>{{ uploadResult.errorRows === 0 ? 'check_circle' : 'warning' }}</mat-icon>
        <div>
          <strong>{{ uploadResult.message }}</strong>
          <div *ngIf="uploadResult.errors?.length > 0" class="error-list">
            <div *ngFor="let e of uploadResult.errors">{{ e }}</div>
          </div>
        </div>
        <button mat-icon-button (click)="uploadResult = null"><mat-icon>close</mat-icon></button>
      </div>

      <!-- Loading -->
      <div *ngIf="loading" class="loading-state"><mat-spinner diameter="40"></mat-spinner></div>

      <!-- Table -->
      <div *ngIf="!loading" class="data-table-container">
        <table class="performance-table">
          <thead>
            <tr>
              <th>Intern</th>
              <th>Intern ID</th>
              <th>College</th>
              <th>Department</th>
              <th>Duration</th>
              <th>Status</th>
              <th>Tasks</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let intern of interns" (click)="viewProfile(intern)" style="cursor: pointer;">
              <td>
                <div class="intern-cell">
                  <div class="intern-avatar">{{ intern.name?.charAt(0) }}</div>
                  <div>
                    <div class="intern-name">{{ intern.name }}</div>
                    <div class="intern-id">{{ intern.email }}</div>
                  </div>
                </div>
              </td>
              <td>{{ intern.internId }}</td>
              <td>{{ intern.college || '-' }}</td>
              <td>{{ intern.department || '-' }}</td>
              <td>{{ intern.startDate | date:'MMM d' }} - {{ intern.endDate | date:'MMM d, y' }}</td>
              <td><span class="status-badge" [ngClass]="'status-' + intern.status?.toLowerCase()">{{ intern.status }}</span></td>
              <td>
                <span class="text-success">{{ intern.completedTasks }}</span> / {{ intern.totalTasks }}
              </td>
              <td>
                <button mat-icon-button matTooltip="View Profile" (click)="viewProfile(intern); $event.stopPropagation()">
                  <mat-icon>visibility</mat-icon>
                </button>
                <button mat-icon-button matTooltip="Delete" color="warn"
                        (click)="deleteIntern(intern); $event.stopPropagation()">
                  <mat-icon>delete</mat-icon>
                </button>
              </td>
            </tr>
            <tr *ngIf="interns.length === 0">
              <td colspan="8" class="empty-state">
                <mat-icon>people_outline</mat-icon>
                <p>No interns found. Upload an Excel file to get started.</p>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  `,
    styles: [`
    .header-row { display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 16px; }
    .header-actions { display: flex; gap: 10px; }

    .upload-btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 10px 20px; border-radius: var(--radius-sm);
      background: linear-gradient(135deg, var(--success), #059669);
      color: white; font-weight: 600; cursor: pointer; transition: all 0.2s;
    }
    .upload-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 15px rgba(16, 185, 129, 0.4); }

    .upload-result {
      display: flex; align-items: flex-start; gap: 12px; padding: 16px;
      border-radius: var(--radius-sm); margin-bottom: 20px;
    }
    .upload-result.success { background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.3); }
    .upload-result.warning { background: rgba(245, 158, 11, 0.1); border: 1px solid rgba(245, 158, 11, 0.3); }
    .error-list { margin-top: 8px; font-size: 12px; color: var(--text-secondary); max-height: 100px; overflow-y: auto; }

    .loading-state { display: flex; justify-content: center; padding: 60px; }

    .performance-table { width: 100%; border-collapse: collapse; }
    .performance-table th {
      text-align: left; padding: 14px 16px; color: var(--text-secondary);
      font-weight: 600; font-size: 12px; text-transform: uppercase;
      letter-spacing: 0.5px; border-bottom: 1px solid var(--border);
    }
    .performance-table td { padding: 14px 16px; border-bottom: 1px solid var(--border); font-size: 14px; }
    .performance-table tr:hover { background: var(--bg-surface); }

    .intern-cell { display: flex; align-items: center; gap: 10px; }
    .intern-avatar {
      width: 36px; height: 36px; border-radius: 50%;
      background: linear-gradient(135deg, var(--primary), var(--secondary));
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; font-size: 14px; color: white; flex-shrink: 0;
    }
    .intern-name { font-weight: 600; }
    .intern-id { font-size: 12px; color: var(--text-muted); }
    .text-success { color: #34d399; font-weight: 600; }

    .empty-state { text-align: center; padding: 40px !important; color: var(--text-muted); }
    .empty-state mat-icon { font-size: 48px; width: 48px; height: 48px; margin-bottom: 8px; }
  `]
})
export class InternListComponent implements OnInit {
    interns: Intern[] = [];
    batches: string[] = [];
    departments: string[] = [];
    searchQuery = '';
    statusFilter = '';
    batchFilter = '';
    deptFilter = '';
    loading = true;
    uploadResult: any = null;

    constructor(
        private internService: InternService,
        private router: Router,
        private snackBar: MatSnackBar
    ) { }

    ngOnInit(): void {
        this.loadInterns();
        this.internService.getFilters().subscribe(f => {
            this.batches = f.batches || [];
            this.departments = f.departments || [];
        });
    }

    loadInterns(): void {
        this.loading = true;
        this.internService.getAll().subscribe(data => {
            this.interns = data;
            this.loading = false;
        });
    }

    onSearch(): void {
        this.loading = true;
        this.internService.search({
            search: this.searchQuery, status: this.statusFilter,
            batch: this.batchFilter, department: this.deptFilter
        }).subscribe(data => {
            this.interns = data;
            this.loading = false;
        });
    }

    onFileUpload(event: any): void {
        const file = event.target.files[0];
        if (!file) return;
        this.internService.uploadExcel(file).subscribe({
            next: (result) => {
                this.uploadResult = result;
                this.loadInterns();
            },
            error: (err) => {
                this.snackBar.open('Upload failed: ' + (err.error?.message || 'Unknown error'), 'Close', { duration: 3000 });
            }
        });
    }

    viewProfile(intern: Intern): void {
        this.router.navigate(['/interns', intern.id]);
    }

    deleteIntern(intern: Intern): void {
        if (confirm(`Delete intern ${intern.name}?`)) {
            this.internService.delete(intern.id!).subscribe(() => {
                this.snackBar.open('Intern deleted', 'Close', { duration: 2000 });
                this.loadInterns();
            });
        }
    }
}
